WITH valid AS (SELECT id, name, email, country, city, segment, is_active, credit_limit, CASE WHEN is_active THEN 'Yes' ELSE 'No' END AS is_active_label, COALESCE(city, 'OTHER') AS city_filled FROM customers WHERE city = 'New York'), kept AS (SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM sessions ch WHERE ch.customer_id = s.id AND ch.started_at < '2025-07-28')), scored AS (SELECT *, AVG(credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS credit_limit_avg_5, LAST_VALUE(credit_limit) IGNORE NULLS OVER (PARTITION BY country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_credit_limit, NTILE(10) OVER (ORDER BY credit_limit DESC, id) AS credit_limit_bucket FROM kept), metrics AS (SELECT *, LAST_VALUE(credit_limit_bucket, TRUE) OVER w_part AS last_known_credit_limit_bucket, SUM(last_known_credit_limit) OVER (PARTITION BY segment ORDER BY credit_limit_avg_5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_last_known_credit_limit FROM scored WINDOW w_part AS (PARTITION BY city ORDER BY credit_limit_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT *, AVG(running_last_known_credit_limit) OVER (PARTITION BY city ORDER BY last_known_credit_limit, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS running_last_known_credit_limit_avg_2_prior, MAX(last_known_credit_limit) OVER (PARTITION BY city) AS city_max_last_known_credit_limit, SUM(last_known_credit_limit) OVER (PARTITION BY city ORDER BY credit_limit_avg_5, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_last_known_credit_limit_2 FROM metrics
